template <typename T>
class SmartResource {
    T* resource;
public:
    SmartResource(T* p) : resource(p) {}
    ~SmartResource() { delete resource; }

    // Overloading '*' (Dereference Context - Unary)
    T& operator*() const {
        return *resource;
    }

    // Overloading '->' (Pointer Access Context - Unary)
    T* operator->() const {
        return resource;
    }

    // Note: operator*(int factor) would be binary (Multiplication Context)
};
